BEGIN;
INSERT INTO "FileUploadGrant" (id,"organizationId","labId","createdByMemberId","boundaryId",purpose,"targetType","targetId",provider,"providerFileKey","correlationId","createdAt","updatedAt","expiresAt","caseClinicalValidatedSuffix") VALUES ('runtime-mismatch-grant','finalize-org','finalize-lab','finalize-member','N-FILE-110','case.asset.add.stage','case','finalize-case','UPLOADTHING','runtime-mismatch-key','runtime-mismatch',(now() at time zone 'UTC')-interval '1 minute',(now() at time zone 'UTC'),(now() at time zone 'UTC')+interval '1 hour','JPG');
SAVEPOINT mismatch;
INSERT INTO "CaseClinicalUploadEvidence" ("uploadGrantId","organizationId","labId","caseId",provider,"providerObjectKey","clinicalPurpose","verifiedFormat","validatedSuffix","measuredSizeBytes",width,height,"contentSha256","validationProfile","validatorVersion","codecBackend","codecPackageVersion","codecLibraryVersion","codecRuntimeSha256","sourceComponents","isProgressive","validatedAt") VALUES ('runtime-mismatch-grant','finalize-org','finalize-lab','finalize-case','UPLOADTHING','runtime-mismatch-key','CLINICAL_REFERENCE_PHOTOGRAPH','JPEG','JPEG',1234,16,16,repeat('a',64),'JPEG_CLINICAL_V1_S001','LABOS_S001_JULUSIAN_V1','JULUSIAN_TURBOJPEG','3.0.1','3.1.3',repeat('b',64),3,false,now());
ROLLBACK TO SAVEPOINT mismatch;
SAVEPOINT wrong_key;
INSERT INTO "CaseClinicalUploadEvidence" ("uploadGrantId","organizationId","labId","caseId",provider,"providerObjectKey","clinicalPurpose","verifiedFormat","validatedSuffix","measuredSizeBytes",width,height,"contentSha256","validationProfile","validatorVersion","codecBackend","codecPackageVersion","codecLibraryVersion","codecRuntimeSha256","sourceComponents","isProgressive","validatedAt") VALUES ('runtime-mismatch-grant','finalize-org','finalize-lab','finalize-case','UPLOADTHING','wrong-key','CLINICAL_REFERENCE_PHOTOGRAPH','JPEG','JPG',1234,16,16,repeat('a',64),'JPEG_CLINICAL_V1_S001','LABOS_S001_JULUSIAN_V1','JULUSIAN_TURBOJPEG','3.0.1','3.1.3',repeat('b',64),3,false,now());
ROLLBACK TO SAVEPOINT wrong_key;
COMMIT;
SELECT (SELECT count(*) FROM "CaseClinicalUploadEvidence" WHERE "uploadGrantId"='runtime-mismatch-grant') AS evidence_count, (SELECT status FROM "FileUploadGrant" WHERE id='runtime-mismatch-grant') AS grant_status;